// qx statusline for Claude Code: prints the previous statusLine command's output
// (if the user had one) followed by `qx gain --line`. Generated by `qx setup`;
// __QX_EXE__ is filled in at write time. Never throws, always exits 0.
const { spawn, execFile } = require("node:child_process");
const fs = require("node:fs");
const path = require("node:path");

const EXE = "__QX_EXE__";
const TIMEOUT_MS = 2000;
// The user's own status line may be slow (git, network); it gets longer than `qx gain --line`.
const PREVIOUS_TIMEOUT_MS = 10000;

// A host that leaves stdin open must not block qx's own line, so we also race a timer.
const STDIN_WAIT_MS = 1000;

function readStdin() {
  return new Promise((resolve) => {
    const chunks = [];
    let settled = false;
    const finish = () => {
      if (!settled) {
        settled = true;
        clearTimeout(timer);
        resolve(Buffer.concat(chunks));
      }
    };
    const timer = setTimeout(finish, STDIN_WAIT_MS);
    try {
      process.stdin.on("data", (c) => chunks.push(c));
      process.stdin.on("end", finish);
      process.stdin.on("close", finish);
      process.stdin.on("error", finish);
    } catch {
      finish();
    }
  });
}

// Claude Code runs statusLine commands through Git Bash on Windows, so a previous
// command written for bash (pipes, $VAR, single quotes) only works there, not in cmd.exe.
// Never plain `bash`: on Windows that is WSL's. No Git Bash found: null.
function findBash() {
  if (process.env.CLAUDE_CODE_GIT_BASH_PATH) return process.env.CLAUDE_CODE_GIT_BASH_PATH;
  const std = "C:/Program Files/Git/bin/bash.exe";
  if (fs.existsSync(std)) return std;
  // Git for Windows' root holds `bin\bash.exe`; git.exe sits in `cmd`, `bin` or `mingw64\bin`.
  for (const raw of (process.env.PATH || "").split(path.delimiter)) {
    const dir = raw.replace(/^"|"$/g, "");
    if (!dir || !fs.existsSync(path.join(dir, "git.exe"))) continue;
    const base = path.basename(dir).toLowerCase();
    if (base !== "cmd" && base !== "bin") continue;
    const parent = path.dirname(dir);
    const roots = [parent];
    if (base === "bin" && path.basename(parent).toLowerCase() === "mingw64") roots.push(path.dirname(parent));
    for (const root of roots) {
      const bash = path.join(root, "bin", "bash.exe");
      if (fs.existsSync(bash)) return bash;
    }
  }
  return null;
}

// Sidecar written by setup holds the statusLine value that was there before qx.
function previousCommand() {
  try {
    const side = JSON.parse(fs.readFileSync(path.join(__dirname, "qx-statusline.json"), "utf8"));
    const cmd = side && side.previous && side.previous.command;
    return typeof cmd === "string" && cmd.trim() ? cmd : null;
  } catch {
    return null;
  }
}

function runPrevious(cmd, input, useBash = process.platform === "win32") {
  return new Promise((resolve) => {
    let out = "";
    let done = false;
    let timer;
    const finish = (value = out) => {
      if (!done) {
        done = true;
        clearTimeout(timer);
        resolve(value);
      }
    };
    try {
      const stdio = ["pipe", "pipe", "ignore"];
      const bash = useBash ? findBash() : null;
      const child = bash
        ? spawn(bash, ["-c", cmd], { windowsHide: true, stdio })
        : spawn(cmd, { shell: true, windowsHide: true, stdio });
      timer = setTimeout(() => {
        try {
          if (process.platform === "win32") {
            // child.kill() only ends the shell; /T takes down the pipeline it started too.
            execFile("taskkill", ["/T", "/F", "/PID", String(child.pid)], { windowsHide: true }, () => {});
          } else {
            child.kill();
          }
        } catch {}
        finish();
      }, PREVIOUS_TIMEOUT_MS);
      // Decode as a stream so multi-byte characters split across chunks stay intact.
      child.stdout.setEncoding("utf8");
      child.stdout.on("data", (d) => (out += d));
      child.on("error", () => {
        // Git Bash would not start: retry once through the default Windows shell.
        if (useBash) finish(runPrevious(cmd, input, false));
        else finish("");
      });
      child.on("close", () => finish());
      child.stdin.on("error", () => {});
      child.stdin.end(input);
    } catch {
      finish(useBash ? runPrevious(cmd, input, false) : "");
    }
  });
}

function runQx() {
  return new Promise((resolve) => {
    try {
      execFile(EXE, ["gain", "--line"], { timeout: TIMEOUT_MS, windowsHide: true }, (err, stdout) => {
        resolve(err ? "" : String(stdout));
      });
    } catch {
      resolve("");
    }
  });
}

async function main() {
  const input = await readStdin();
  const cmd = previousCommand();
  const [prev, qx] = await Promise.all([cmd ? runPrevious(cmd, input) : "", runQx()]);
  const parts = [prev.replace(/\r?\n$/, ""), qx.replace(/\r?\n$/, "")].filter((p) => p.length > 0);
  if (parts.length) process.stdout.write(parts.join("\n") + "\n");
}

main().then(
  () => process.exit(0),
  () => process.exit(0),
);
